class ActivationBlock {
    HHOOK hook_=nullptr,paint_=nullptr;
public:
    ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int n,WPARAM w,LPARAM l)->LRESULT{return n==HCBT_ACTIVATE||n==HCBT_MINMAX?1:CallNextHookEx(nullptr,n,w,l);},nullptr,GetCurrentThreadId());paint_=SetWindowsHookEx(WH_CALLWNDPROC,[](int n,WPARAM w,LPARAM l)->LRESULT{if(n>=0){const auto* m=reinterpret_cast<CWPSTRUCT*>(l);if(m->message==WM_WINDOWPOSCHANGING&&GetAncestor(m->hwnd,GA_ROOT)==m->hwnd){auto* p=reinterpret_cast<WINDOWPOS*>(m->lParam);p->flags=(p->flags&~SWP_SHOWWINDOW)|SWP_NOACTIVATE;}}return CallNextHookEx(nullptr,n,w,l);},nullptr,GetCurrentThreadId());if(!hook_||!paint_)throw std::runtime_error("Cannot isolate workflow native windows");}
    ~ActivationBlock(){if(paint_)UnhookWindowsHookEx(paint_);if(hook_)UnhookWindowsHookEx(hook_);}
};
